public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Calculate the number of octets to read
    int octetsToRead = bb.remaining() - i;

    // Check if the number of octets is valid
    if (octetsToRead < 1 || octetsToRead > 4) {
        throw new IllegalArgumentException("Invalid number of octets to read: " + octetsToRead);
    }

    // Create a byte array to hold the octets
    byte[] octets = new byte[octetsToRead];

    // Read the octets from the byte buffer
    bb.get(octets, 0, octetsToRead);

    // Decode the octets using the UTF-8 decoding
    String decodedString = new String(octets, StandardCharsets.UTF_8);

    // Append the decoded string to the string builder
    sb.append(decodedString);

    // Return the index to the next unchecked character
    return i + octetsToRead;
}

