/**
* Splits a String at the first occurrence of the delimiter.
* Does not include the delimiter in the result.
* @param toSplit the string to split
* @param delimiter to split the string up with
* @return a two element array with index 0 being before the delimiter, andindex 1 being after the delimiter (neither element includes the delimiter); or `null` if the delimiter wasn't found in the given input String
*/
public static String[] split(String toSplit, String delimiter) {
    if (toSplit == null || delimiter == null) {
        return null;
    }
    int index = toSplit.indexOf(delimiter);
    if (index == -1) {
        return null;
    }
    String[] result = new String[2];
    result[0] = toSplit.substring(0, index);
    result[1] = toSplit.substring(index + 1);
    return result;
}

