private List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize a list to store the lower bounds
    List<Integer> lowerBounds = new ArrayList<>();

    // Iterate over the keys and calculate the lower bound for each key
    for (K key : keys) {
        int lowerBound = 0;
        for (K otherKey : keys) {
            if (otherKey.compareTo(key) < 0) {
                lowerBound++;
            }
        }
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}

