/** 
 * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
 * @param path the path to start from (usually a full file path)
 * @param relativePath the relative path to apply(relative to the full file path above)
 * @return the full file path that results from applying the relative path
 */
public static String applyRelativePath(String path, String relativePath) {
    // Convert the relative path to a list of path components
    List<String> relativeComponents = Arrays.asList(relativePath.split("/"));

    // Initialize the stack to hold the path components
    Stack<String> stack = new Stack<>();

    // Push each path component onto the stack
    for (String component : relativeComponents) {
        stack.push(component);
    }

    // Loop through the path components, resolving ".." and "." components
    while (!stack.isEmpty()) {
        String component = stack.pop();

        if (component.equals("..")) {
            // ".." means to go up one directory
            stack.pop();
        } else if (component.equals(".")) {
            // "." means to stay in the current directory
        } else {
            // Push the component onto the stack
            stack.push(component);
        }
    }

    // Join the path components together, separated by "/"
    StringBuilder builder = new StringBuilder();
    for (String component : stack) {
        builder.append("/").append(component);
    }

    // Return the full file path
    return builder.toString();
}

